def evaluate(current_reputation, observation, my_history, round_num):
    # Moving average style update: weight recent observations more
    # Base update: +0.2 for donation, -0.2 for defection
    if observation["action"] == "donate":
        delta = 0.2
        # Boost if we have been cooperative in recent rounds (last 3)
