            recent_self = [h["action"] for h in my_history[-3:]]
            if recent_self.count("donate") >= 2:
                delta += 0.05
    else:
        delta = -0.2
        # Penalize less if we also defected recently (mirroring)
        if my_history and my_history[-1]["action"] == "donate":
            delta -= 0.1  # harsher if we were generous and they defected
    # Blend with current reputation (smoothing)
    new_rep = 0.85 * current_reputation + 0.15 * (current_reputation + delta)
    # Decay slightly to prevent explosion
    new_rep = new_rep * 0.98
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Dynamic threshold: more forgiving later, less forgiving if we've been defected often
    base_threshold = 0.4 - 0.1 * (round_num / 200)  # from 0.4 down to ~0.2 by round 200
    # Adjust based on own recent behavior: if recently donated, be more trusting
    if my_history and len(my_history) >= 3:
        recent_self = [h["action"] for h in my_history[-3:]]
        kindness = recent_self.count("donate") / 3
        threshold = base_threshold - 0.2 * kindness  # lower threshold if we're nice
    else:
        threshold = base_threshold
    # Also consider if the partner has been cooperative in previous encounters?
    # But we only have reputation, so just use that.
    return recipient_reputation > threshold
